package gitv1

import (
	"crypto/rand"
	"encoding/hex"
	"strings"
)

// A receive ID is generated by the worker once per receive and, on the kernel,
// carries the grant it was made under: rcv_<32 lowercase hex>_<grantId>. The
// worker's journal keeps the receive ID of every entry, so a receive whose
// outcome report was lost can be attributed to its credential (and through it to
// its actor and run) when the worker re-reports it, with no push-record table.
// The grant ID inside it is a claim of the worker, which the control plane
// verifies against the credential store; it is never trusted on its own.
const receiveIDPrefix = "rcv_"

const receiveRandomHexLen = 32

// NewReceiveID builds the ID of a receive made under grantID. A grant that is
// not a valid ID, or whose ID would exceed the identifier bound, yields a plain
// random receive ID that names no grant.
func NewReceiveID(grantID string) string {
	var b [receiveRandomHexLen / 2]byte
	if _, err := rand.Read(b[:]); err != nil {
		panic("gitv1: no randomness: " + err.Error())
	}
	id := receiveIDPrefix + hex.EncodeToString(b[:])
	if checkID("grantId", grantID) != nil {
		return id
	}
	if with := id + "_" + grantID; checkID("receiveId", with) == nil {
		return with
	}
	return id
}

// GrantOfReceive returns the grant ID a receive ID carries.
func GrantOfReceive(receiveID string) (string, bool) {
	rest, ok := strings.CutPrefix(receiveID, receiveIDPrefix)
	if !ok || len(rest) <= receiveRandomHexLen+1 || rest[receiveRandomHexLen] != '_' {
		return "", false
	}
	for _, c := range rest[:receiveRandomHexLen] {
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return "", false
		}
	}
	grant := rest[receiveRandomHexLen+1:]
	if checkID("grantId", grant) != nil {
		return "", false
	}
	return grant, true
}
